    let damage = clamp(in.color.a, 0.0, 1.0);
    
    // Thin crack lines on the surface
    let crackNoise = noise3(in.localPos * 4.2);
    let crackPattern = pow(1.0 - abs(crackNoise * 2.0 - 1.0), 8.0); // sharp ridged valleys
    
