  let n1 = noise3D(in.localPos * 16.0);
  let n2 = noise3D(in.localPos * 36.0 + vec3f(1.7, 3.1, 0.5)) * 0.5;
  let bioGrain = 1.0 + (n1 + n2) * 0.07;

